// The plant library. Every number here feeds the advisor, which judges each plant against
// the site's own climate, so the values are the plant's real tolerances, not regional advice:
//   zoneMin/zoneMax  USDA hardiness range the plant survives and produces in
//   chill            [lowest-chill variety, typical] hours between 0 and 7.2 C it needs in winter
//   heatMaxC         hottest-month mean daily maximum above which it struggles
//   crop             annual timing: frost kill temperature, the mean daily temperature it needs
//                    at planting, the mean daily maximum above which it bolts or will not set,
//                    days to maturity (from transplanting when transplanted), method, spacing
// Months are northern hemisphere; the advisor shifts them for southern sites.
// Sources: US cooperative extension vegetable and fruit guides, RHS, seed company growing
// data, USDA PLANTS; chill ranges from university low-chill variety trials.

export type Layer = 'canopy' | 'subcanopy' | 'shrub' | 'herb' | 'groundcover' | 'vine' | 'root';
export type Form = 'round' | 'conical' | 'columnar' | 'spreading' | 'vase' | 'weeping' | 'palm' | 'shrub' | 'clump' | 'mat' | 'vine';
export type Category =
  | 'vegetable' | 'herb' | 'flower' | 'perennial-veg' | 'fruit-tree' | 'nut-tree' | 'berry' | 'vine'
  | 'support' | 'grain' | 'cover' | 'pasture' | 'timber' | 'indoor';

export interface Crop {
  season: 'cool' | 'warm';
  killC: number; // air temperature that kills it
  plantMinC: number; // mean daily air temperature needed at sowing or planting out
  growMaxC: number; // mean daily maximum while maturing above which it bolts, will not set or sulks
  days: number; // to first harvest: from transplanting for transplants, from sowing otherwise
  method: 'direct' | 'transplant' | 'either' | 'tuber' | 'slips' | 'sets' | 'fall';
  indoorWeeks?: number; // weeks to raise a transplant
  emergeDays?: number; // days in the ground before any frost-tender growth shows (tubers)
  harvestWeeks: number;
  setMinNightC?: number; // nights must average at least this while it flowers and fruits
  daylengthBulb?: boolean; // bulbs when days lengthen past a trigger set by the variety type (onions)
  tropicalOk?: boolean; // shrugs off hot, wet tropical summers that rot temperate vegetables
  nightMaxC?: number; // and no more than this (tomatoes drop flowers, potatoes stop making tubers)
  successionDays?: number;
  depthCm: number;
  spacingCm: number;
  rowCm?: number;
}

export interface Variety { when: { chillMax?: number; chillMin?: number; zoneMax?: number; zoneMin?: number; latMax?: number; latMin?: number; humid?: boolean; dry?: boolean; hot?: boolean; coolSummer?: boolean; shortSeason?: boolean }; text: string }

export interface Species {
  id: string;
  name: string;
  latin: string;
  category: Category;
  life: 'annual' | 'biennial' | 'perennial';
  pz: number[]; // permaculture zones it belongs in
  layer: Layer;
  form: Form;
  deciduous: boolean;
  heightM: number;
  spreadM: number;
  yearsToMature: number;
  zoneMin: number;
  zoneMax: number;
  chill?: [number, number];
  heatMaxC?: number;
  gddMin?: number; // growing degree days (base 10 C) a year it needs to ripen
  frostFreeMin?: number; // frost-free days it needs to ripen its crop
  humidOk?: boolean; // false: suffers in humid summers (disease, rot)
  dryOk?: boolean; // false: needs humid air or rainfall, struggles in deserts
  water: 'low' | 'medium' | 'high';
  sun: 'full' | 'part' | 'shade';
  ph?: [number, number];
  wetOk?: boolean;
  droughtOk?: boolean;
  container?: boolean; // can live in a pot and come indoors for winter
  crop?: Crop;
  spacingM?: number; // planting distance for perennials
  stock?: string; // how it is usually planted
  firstHarvestYears?: number;
  functions: string[];
  harvest: number[];
  prune: number[];
  varieties?: Variety[];
  notes?: string;
  caution?: string;
  leaf: string;
  fall?: string;
  fruit?: string;
  flower?: string;
  bloom?: number[];
  costUSD: number;
}

type P = Partial<Species> & Pick<Species, 'id' | 'name' | 'latin'>;

const tree = (o: P & { category?: Category }): Species => ({
  category: 'fruit-tree', life: 'perennial', pz: [2], layer: 'subcanopy', form: 'round', deciduous: true,
  heightM: 6, spreadM: 5, yearsToMature: 6, zoneMin: 5, zoneMax: 9, water: 'medium', sun: 'full',
  functions: [], harvest: [], prune: [1, 2], leaf: '#4f8a34', costUSD: 35, stock: 'bare-root or container tree',
  firstHarvestYears: 3, ...o,
} as Species);

const shrub = (o: P & { category?: Category }): Species => ({
  category: 'berry', life: 'perennial', pz: [2], layer: 'shrub', form: 'shrub', deciduous: true,
  heightM: 2, spreadM: 1.5, yearsToMature: 3, zoneMin: 4, zoneMax: 8, water: 'medium', sun: 'full',
  functions: [], harvest: [], prune: [2], leaf: '#4a8034', costUSD: 15, stock: 'bare-root or potted plant',
  firstHarvestYears: 2, ...o,
} as Species);

const perennial = (o: P & { category?: Category }): Species => ({
  category: 'herb', life: 'perennial', pz: [1], layer: 'herb', form: 'clump', deciduous: true,
  heightM: 0.5, spreadM: 0.5, yearsToMature: 1, zoneMin: 4, zoneMax: 9, water: 'medium', sun: 'full',
  functions: [], harvest: [], prune: [], leaf: '#5a8a4a', costUSD: 6, stock: 'potted plant or division',
  firstHarvestYears: 1, ...o,
} as Species);

const annual = (o: P & { crop: Crop; category?: Category }): Species => ({
  category: 'vegetable', life: 'annual', pz: [1], layer: 'herb', form: 'clump', deciduous: true,
  heightM: 0.5, spreadM: 0.4, yearsToMature: 0.25, zoneMin: 0, zoneMax: 14, water: 'medium', sun: 'full',
  functions: [], harvest: [], prune: [], leaf: '#4a8a3a', costUSD: 1, ...o,
} as Species);

// crop helpers: cool-season and warm-season defaults
const cool = (c: Partial<Crop> & Pick<Crop, 'days' | 'method' | 'spacingCm'>): Crop => ({ season: 'cool', killC: -4, plantMinC: 5, growMaxC: 27, harvestWeeks: 4, depthCm: 1, ...c });
const warm = (c: Partial<Crop> & Pick<Crop, 'days' | 'method' | 'spacingCm'>): Crop => ({ season: 'warm', killC: 0, plantMinC: 16, growMaxC: 34, harvestWeeks: 6, depthCm: 2, ...c });

